// A prompt, or a refusal — not a model call on `undefined`.
const body = $json.body || {};
const prompt = typeof body.prompt === 'string' ? body.prompt.trim() : '';
if (!prompt) {
  throw new Error('the request body needs a non-empty "prompt" string');
}
if (prompt.length > 2000) {
  throw new Error('prompt is longer than 2000 characters');
}
return [{ json: { prompt } }];

const msg = (($json.choices || [])[0] || {}).message || {};
const answer = (msg.content || '').trim();
if (!answer) {
  throw new Error('the model returned no content: ' + JSON.stringify($json).slice(0, 300));
}
return [{ json: { prompt: $('Validate the request').first().json.prompt, answer } }];
